for (const [instrumentKey, revision] of checked.marks) {
  tx.require({
    name: `mark:${instrumentKey}@${binding.reviewDate}`,
    store: 'observations',
    key: [binding.reviewDate, instrumentKey],
    verify: (current) => (current?.['resolutionRevision'] ?? 'None') === revision,
  });
}
